use serde_json::{json,Value};
use sha2::{Digest,Sha256};
use std::{collections::{BTreeMap,BTreeSet},fs,path::Path};
const R:&str="/home/ubuntu/src/zopro-perf-work/calibrated-compiler176";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn digest(b:&[u8])->String{format!("{:x}",Sha256::digest(b))}
fn hash(p:impl AsRef<Path>)->String{digest(&fs::read(p).unwrap())}
fn save(p:&str,v:&Value){fs::write(format!("{R}/{p}"),serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn main(){
 assert!(!Path::new(R).join("qualification.json").exists());
 let patch=read(format!("{R}/patch-result.json"));assert_eq!(patch["inverse_exact"],true);
 let cpu_path=format!("{R}/source/llvm/lib/Target/X86/X86.td");
 let mut source_count=0;let mut changed=Vec::new();
 for line in fs::read_to_string(format!("{R}/source-before.sha256")).unwrap().lines(){let (expected,p)=line.split_once("  ").unwrap();assert_eq!(expected.len(),64);let got=hash(p);source_count+=1;if got!=expected{assert_eq!(p,cpu_path);assert_eq!(json!(expected),patch["cpu_before"]);assert_eq!(json!(got),patch["cpu_after"]);changed.push(p.to_string());}}
 assert_eq!(source_count,77147);assert_eq!(changed,vec![cpu_path.clone()]);
 let cpu=fs::read_to_string(&cpu_path).unwrap();let original_cpu=fs::read_to_string(format!("{R}/research/X86.td")).unwrap();
 assert_eq!(cpu,original_cpu.replacen("include \"X86ScheduleZnver4.td\"","include \"X86ScheduleZnver4.td\"\ninclude \"X86ScheduleZoproZnver5.td\"",1).replacen("ProcModel<\"znver5\", Znver4Model,","ProcModel<\"znver5\", ZoproZnver5Model,",1));
 let candidate=fs::read_to_string(format!("{R}/source/llvm/lib/Target/X86/X86ScheduleZoproZnver5.td")).unwrap();assert_eq!(json!(digest(candidate.as_bytes())),patch["private_model"]);
 let marker=candidate.find("\n// Private partial Zen5 calibration.").unwrap();let close=candidate.rfind("} // SchedModel").unwrap();
 let inverse=format!("{}{}",&candidate[..marker],&candidate[close..]).replace("\"VPMADD52(H|L)UQ(Z128|Z256)(r|rk|rkz)\",\n        \"VPMADD52(H|L)UQZ(rk|rkz)\"","\"VPMADD52(H|L)UQ(Z|Z128|Z256)(r|rk|rkz)\"").replacen("(instrs VPSUBBZrr, VPSUBWZrr, VPSUBDZrr,","(instrs VPSUBBZrr, VPSUBWZrr, VPSUBDZrr, VPSUBQZrr,",1).replace("ZoproZnver5","Znver4").replace("ZoproZn5","Zn4");
 assert_eq!(inverse,fs::read_to_string(format!("{R}/research/X86ScheduleZnver4.td")).unwrap());
 let mut pins=BTreeMap::new();let mut receipt_count=0;let mut receipts=vec![];
 for (stage,count) in [("source",2),("build-OFF",3),("ir",2),("build-ON",9),("provenance",2),("codegen",5),("inspect",12),("correctness",324)]{
  let plan=read(format!("{R}/{stage}-plan.json"));let result=read(format!("{R}/{stage}-runs/result.json"));assert_eq!(result["status"],"complete");let steps=plan["steps"].as_array().unwrap();assert_eq!(steps.len(),count);assert_eq!(result["steps"].as_array().unwrap().len(),count);
  for(p,h)in read(plan["source_pins"].as_str().unwrap()).as_object().unwrap(){if let Some(old)=pins.insert(p.clone(),h.clone()){assert_eq!(&old,h);}}
  for step in steps{let name=step["name"].as_str().unwrap();let dir=format!("{R}/{stage}-runs/{name}");let exit=read(format!("{dir}/exit.json"));assert_eq!(exit["success"],true);assert_eq!(exit["returncode"],0);assert_eq!(exit["stdout_sha256"],hash(format!("{dir}/stdout.log")));assert_eq!(exit["stderr_sha256"],hash(format!("{dir}/stderr.log")));let command=read(format!("{dir}/command.json"));assert_eq!(&command["argv"].as_array().unwrap()[4..],step["argv"].as_array().unwrap());receipts.push(json!({"stage":stage,"name":name,"exit_sha256":hash(format!("{dir}/exit.json"))}));receipt_count+=1;}
 }
 assert_eq!(receipt_count,359);for(p,h)in &pins{assert_eq!(h,&json!(hash(p)),"pin {p}");}
 let load_scope=|role:&str,cpu:&str|read(format!("{R}/build-ON-runs/scope-{role}-{cpu}/stdout.log"));
 let off=load_scope("OFF","znver5");let on=load_scope("ON","znver5");let zn4=load_scope("ON","znver4");
 let a=off["CodeRegions"][0]["InstructionInfoView"]["InstructionList"].as_array().unwrap();let b=on["CodeRegions"][0]["InstructionInfoView"]["InstructionList"].as_array().unwrap();let c=zn4["CodeRegions"][0]["InstructionInfoView"]["InstructionList"].as_array().unwrap();assert_eq!(a.len(),18);assert_eq!(b.len(),18);assert_eq!(a,c);
 for i in 0..18{assert_eq!(off["CodeRegions"][0]["Instructions"][i],on["CodeRegions"][0]["Instructions"][i]);if i<4{assert_eq!(b[i]["Latency"],if i<2{4}else{2});assert_eq!(b[i]["RThroughput"],if i<2{0.5}else{0.25});assert_ne!(a[i],b[i]);}else{assert_eq!(a[i],b[i]);}}
 let selection=read(format!("{R}/selected-functions.json"));assert_eq!(selection.as_array().unwrap().len(),3);
 let ir=fs::read_to_string(format!("{R}/native/original-rustc.ll")).unwrap();let attrs=ir.lines().filter(|l|l.starts_with("attributes #1 =")||l.starts_with("attributes #2 =")).collect::<Vec<_>>();assert_eq!(attrs.len(),2);for s in attrs{assert!(s.contains("\"target-cpu\"=\"znver5\"")&&s.contains("+avx512ifma"));}
 let mut rows=vec![];let mut sequences=BTreeMap::new();
 for role in ["ORIGINAL","OFF","ON"]{let symbols=fs::read_to_string(format!("{R}/inspect-runs/symbols-{role}/stdout.log")).unwrap();for f in selection.as_array().unwrap(){let raw=f["symbol"].as_str().unwrap();let kind=f["kind"].as_str().unwrap();let matches=symbols.lines().filter_map(|l|{let v=l.split_whitespace().collect::<Vec<_>>();(v.len()==4&&v[3]==raw).then_some(v)}).collect::<Vec<_>>();assert_eq!(matches.len(),1);let start=u64::from_str_radix(matches[0][0],16).unwrap();let size=u64::from_str_radix(matches[0][1],16).unwrap();let file=format!("{R}/inspect-runs/decode-{role}-{kind}/stdout.log");let text=fs::read_to_string(&file).unwrap();let inst=text.lines().filter_map(|l|{let(a,s)=l.trim().split_once(':')?;let ip=u64::from_str_radix(a,16).ok()?;(ip>=start&&ip<start+size).then_some(s.trim())}).collect::<Vec<_>>();assert!(inst.len()>1000);let seq=inst.iter().map(|s|s.split_whitespace().next().unwrap()).collect::<Vec<_>>().join("\n");let count=|m:&str|inst.iter().filter(|s|s.split_whitespace().next()==Some(m)).count();let ifma=inst.iter().filter(|s|s.starts_with("vpmadd52")).count();assert_eq!(ifma,match kind{"G1"=>800,"G2"=>1450,_=>500});sequences.insert((role,kind),seq.clone());rows.push(json!({"role":role,"kind":kind,"symbol":raw,"start":start,"size_bytes":size,"instruction_rows":inst.len(),"ifma":ifma,"add":count("vpaddq"),"sub":count("vpsubq"),"vector_stack_operand_rows":inst.iter().filter(|s|s.starts_with('v')&&(s.contains("[rsp")||s.contains("[rbp"))).count(),"opcode_sequence_sha256":digest(seq.as_bytes()),"disassembly":file,"disassembly_sha256":digest(text.as_bytes())}));}}
 for kind in ["G1","G2"]{assert_ne!(sequences[&("OFF",kind)],sequences[&("ON",kind)],"no scheduling change in {kind}");}
 let original_link=read(format!("{R}/original-link.json"));assert_eq!(read(format!("{R}/original-link-exit.json"))["success"],true);
 for role in ["OFF","ON"]{let linked=read(format!("{R}/link-{role}.json"));assert_eq!(read(format!("{R}/link-{role}-exit.json"))["success"],true);let mut expected=original_link["argv"].as_array().unwrap().clone();let objects=expected.iter().enumerate().filter(|(_,v)|v.as_str().unwrap().ends_with(".rcgu.o")).map(|(i,_)|i).collect::<Vec<_>>();assert_eq!(objects.len(),1);expected[objects[0]]=json!(format!("{R}/native/{role}.o"));let i=expected.iter().position(|v|v=="-o").unwrap();expected[i+1]=json!(format!("{R}/native/caller-{role}"));assert_eq!(linked["argv"],json!(expected));assert_eq!(linked["cwd"],original_link["cwd"]);assert_eq!(linked["program"],original_link["program"]);}
 let plan=read(format!("{R}/correctness-plan.json"));let mut cases:BTreeMap<String,BTreeMap<String,Value>>=BTreeMap::new();
 for step in plan["steps"].as_array().unwrap(){let name=step["name"].as_str().unwrap();let log=fs::read_to_string(format!("{R}/correctness-runs/{name}/stdout.log")).unwrap();let lines=log.lines().filter_map(|l|l.strip_prefix("CALLER ")).collect::<Vec<_>>();assert_eq!(lines.len(),1);let v:Value=serde_json::from_str(lines[0]).unwrap();let arm=name.split('-').next().unwrap();assert_eq!(v["arm"],"OFF");assert_eq!(v["rounds_per_worker"],64);assert_eq!(v["timed_allocations"],0);assert_eq!(v["complete_generator_oracle"],true);assert_eq!(v["new_proofs"],0);assert_eq!(v["priming_passes"],3);assert_eq!(v["priming_rounds"],128);let w=v["workers"].as_u64().unwrap();let mappings=v["worker_rows"].as_array().unwrap();assert_eq!(mappings.len(),w as usize);let tids=mappings.iter().map(|v|v["tid"].as_u64().unwrap()).collect::<BTreeSet<_>>();assert_eq!(tids.len(),w as usize);for (i,row)in mappings.iter().enumerate(){assert_eq!(row["worker"],i);assert_eq!(row["cpu"],if w==1{2}else{i});}assert_eq!(v["output_sha256"].as_str().unwrap().len(),64);let key=format!("{}-{}-w{}",v["kind"].as_str().unwrap(),v["size"],w);assert_eq!(name,format!("{arm}-{key}"));assert!(cases.entry(key).or_default().insert(arm.into(),v).is_none());}
 assert_eq!(cases.len(),108);for variants in cases.values(){assert_eq!(variants.len(),3);for role in ["OFF","ON"]{for key in ["output_sha256","scratch_capacity_bytes_by_worker"]{assert_eq!(variants["ORIGINAL"][key],variants[role][key]);}}}
 let binaries=[("ORIGINAL","original-rustc"),("OFF","caller-OFF"),("ON","caller-ON")].into_iter().map(|(role,name)|{let p=format!("{R}/native/{name}");(role,json!({"path":p,"sha256":hash(&p)}))}).collect::<BTreeMap<_,_>>();
 save("qualification.json",&json!({"status":"pass","llvm_commit":"52ed14fcd56afc30f9cccd8ca8ce237c2eef7e04","visible_llvm_source_files_checked":source_count,"changed_original_source_files":changed,"new_private_model":patch["private_model"],"independent_source_inverse":true,"selected_model_rows":4,"unselected_model_rows_unchanged":14,"znver4_model_unchanged":true,"successful_commands_checked":receipt_count,"unique_pins_checked":pins.len(),"correctness_callers":324,"contexts":108,"output_hashes_and_capacities_agree":true,"rows":rows,"binaries":binaries,"receipts":receipts,"new_proofs":0,"proof_ledger":30846,"production_changed":false,"adopted":false,"latency_trial_run":false,"limits":["Only selected register costs are corrected; shift, memory and masked entries and physical-resource mappings remain inherited.","Static instruction counts and reordering do not establish speed, dynamic work or spill cost.","Caller tests do not qualify the full SDK, all native field/core/prover suites, portability or device/resource behavior.","Original Rust and re-emitted OFF differ slightly; calibration remains required.","The compiler inputs share one optimized IR; no Rust field algorithm or architecture changed."]}));
 save("qualification-pins.json",&json!(pins));
 println!("PASS: {source_count} visible source files, {receipt_count} command receipts, 324 oracle callers/108 contexts, 9 decodes; no speed claim");for row in rows{println!("{} {} rows{} IFMA{} stack{}",row["role"],row["kind"],row["instruction_rows"],row["ifma"],row["vector_stack_operand_rows"]);}
}
